import{_ as t,a as n,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Delete Inventory Source","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-inventory-source-delete-gql","title":"Delete Inventory Source","description":"Delete a single inventory source. The response echoes the deleted record.","query":"mutation DeleteAdminSettingsInventorySource($input: deleteAdminSettingsInventorySourceInput!) {\\n  deleteAdminSettingsInventorySource(input: $input) {\\n    adminSettingsInventorySource {\\n      id\\n      _id\\n      code\\n      name\\n      contactEmail\\n      priority\\n      status\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/settings/inventory-sources/62\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"deleteAdminSettingsInventorySource\\": {\\n      \\"adminSettingsInventorySource\\": {\\n        \\"id\\": \\"/api/admin/settings/inventory-sources/62\\",\\n        \\"_id\\": 62,\\n        \\"code\\": \\"throwaway_gqltest\\",\\n        \\"name\\": \\"Throwaway GQL Test\\",\\n        \\"contactEmail\\": \\"qa@example.com\\",\\n        \\"priority\\": 1,\\n        \\"status\\": 1,\\n        \\"message\\": \\"Inventory source deleted successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/settings/inventory-sources/delete.md","filePath":"api/graphql-api/admin/settings/inventory-sources/delete.md","lastUpdated":1787290888000}'),s={name:"api/graphql-api/admin/settings/inventory-sources/delete.md"};function a(i,e,d,c,l,u){return o(),n("div",null,e[0]||(e[0]=[r('<h1 id="delete-inventory-source" tabindex="-1">Delete Inventory Source <a class="header-anchor" href="#delete-inventory-source" aria-label="Permalink to &quot;Delete Inventory Source&quot;">​</a></h1><p>Deletes a single inventory source by its IRI <code>id</code>.</p><p>For field meanings and the delete guards, see the <a href="/api/graphql-api/admin/settings/inventory-sources/">Inventory Sources overview</a>.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>deleteAdminSettingsInventorySource(input:)</code></td><td>Mutation</td><td>Delete an inventory source</td></tr></tbody></table><p>The <code>input.id</code> is the resource IRI. Use the <a href="./list.html"><code>adminSettingsInventorySources</code></a> query to discover valid ids.</p><p>The mutation returns the deleted record under <code>adminSettingsInventorySource</code> — its <code>id</code> (IRI), <code>_id</code> (numeric) and scalar fields all resolve, so you can confirm exactly which source was removed.</p><p>Select <strong><code>message</code></strong> for the success confirmation — it resolves to <code>&quot;Inventory source deleted successfully.&quot;</code> on a successful delete. <code>message</code> is <code>null</code> on read / list / create / update; a failed delete returns a top-level <code>errors[]</code> entry instead.</p><h3 id="delete-guards" tabindex="-1">Delete guards <a class="header-anchor" href="#delete-guards" aria-label="Permalink to &quot;Delete guards&quot;">​</a></h3><p>A delete is <strong>refused</strong> (error, equivalent to HTTP 422 on REST) when it would remove the <strong>last remaining</strong> inventory source, or when the source is still <strong>referenced by product inventories</strong>. Re-assign or zero out those product quantities first.</p><p>Permission: <code>settings.inventory_sources.delete</code>.</p>',11)]))}const m=t(s,[["render",a]]);export{h as __pageData,m as default};
